const fs = require('node:fs');
const path = require('node:path');
const root = __dirname;
const code = [
  '// Generated by node build.cjs. No dependencies, network access, or credentials.',
  fs.readFileSync(path.join(root, 'model.js'), 'utf8'),
  fs.readFileSync(path.join(root, 'plugin.js'), 'utf8')
].join('\n\n');
fs.writeFileSync(path.join(root, 'code.js'), code);
console.log('Built code.js');
